package com.rezoxnemesis.videostudio;

import android.app.*;
import android.graphics.Bitmap;
import android.text.*;
import android.view.*;
import android.widget.*;
import org.json.*;
import java.util.*;
import java.util.concurrent.*;

/** Guided native acting with editable advanced poses and verified imported dialogue. */
final class SketchHumanDialog {
    private static final String[] LEGACY_VIEWS={"front","left","right","back","high","low"};
    private static final String[] ANATOMY_VIEWS={"front","left","right","back","high","low","three_quarter_left","three_quarter_right"};
    private final Activity activity;private final JSONObject document;private final SketchConstructionSubmit submit;
    private final LinearLayout form,poseForm;private final Spinner view,build,hair,faceStyle,shading,clothing,figureStyle,preset,selection,easing,stageLocation,stageTime,stageWeather,propKind;
    private final Map<String,EditText> settings=new LinkedHashMap<>(),channels=new LinkedHashMap<>();
    private final EditText poseFrame,previewFrame,curves,speech,shotStart,motion,overrides,blinkTiming;private final CheckBox custom,timed,fit,naturalBlink,ground,constructionGuides;private final ImageView preview;private final TextView status;
    private final ExecutorService worker=Executors.newSingleThreadExecutor();private Future<?> task,speechTask;private Bitmap bitmap;private JSONArray poses;private int selected,generation,saveGeneration;private boolean binding,closed,saving;private AlertDialog dialog;
    static void show(Activity a,JSONObject doc,SketchConstructionSubmit submit)throws Exception {new SketchHumanDialog(a,doc,submit).show();}
    private SketchHumanDialog(Activity a,JSONObject doc,SketchConstructionSubmit submit)throws Exception {
        activity=a;document=SketchDocument.copy(doc);this.submit=submit;int count=doc.getInt("frameCount");if(count<24||count>1200||count/(double)doc.getInt("fps")>40)throw SketchDocument.bad("Human acting needs24..1200frames, at most40seconds. Set Timing/canvas first.");
        form=new LinearLayout(a);form.setOrientation(1);form.setPadding(20,12,20,12);TextView description=new TextView(a);description.setText("Create original full-body acting on a new editable layer. Choose a starting action, then edit joint poses if needed. Legacy has six authored2D views; anatomy sketch has eight and draws an adult study in neutral shorts, with optional construction guides. Anatomy uses its own face and linework; face structure, shading and light angle apply to Legacy. Colors below stay editable. Projected joints do not certify3D or finished acting. Native preview is silent. Imported speech audio stays in its original project audio lane.");form.addView(description);
        figureStyle=spinner(form,"Figure style",new String[]{"legacy","anatomy_sketch"});constructionGuides=new CheckBox(a);constructionGuides.setText("Construction guides");constructionGuides.setContentDescription("Construction guides");form.addView(constructionGuides);
        view=spinner(form,"Human view",LEGACY_VIEWS);build=spinner(form,"Adult build",new String[]{"slender","broad"});hair=spinner(form,"Hair style",new String[]{"short","long"});faceStyle=spinner(form,"Face structure",new String[]{"graphic","angular","soft"});shading=spinner(form,"Surface shading",new String[]{"cel","soft"});clothing=spinner(form,"Clothing",new String[]{"legacy","tailored"});preset=spinner(form,"Starting action",SketchHumanPresets.NAMES);
        JSONObject defaults=SketchHumanFigure.defaults();for(String key:new String[]{"x","floorY","size","lightAngle","skinColor","hairColor","coatColor","trouserColor"})settings.put(key,input(form,key,String.valueOf(defaults.get(key))));
        motion=input(form,"Motion controls (editable JSON)","{\"phase\":0,\"speed\":1,\"travelScale\":1,\"groundSlope\":0,\"direction\":1,\"strength\":1,\"armSwing\":1}");
        overrides=input(form,"Hold / gaze overrides (editable JSON)","{}");button(form,"Neutral anatomy stance",this::neutralAnatomyStance);
        naturalBlink=new CheckBox(a);naturalBlink.setText("Natural blinks");naturalBlink.setChecked(true);form.addView(naturalBlink);blinkTiming=input(form,"Blink timing (editable JSON)","{}");
        fit=new CheckBox(a);fit.setText("Keep entire motion on canvas (solo studies)");fit.setChecked(true);form.addView(fit);
        stageLocation=spinner(form,"Optional scenery",new String[]{"none","forest_path","bridge","shelter","village"});stageTime=spinner(form,"Scene light",new String[]{"dusk","night","dawn"});stageWeather=spinner(form,"Scene weather",new String[]{"clear","wind","rain"});propKind=spinner(form,"Optional held prop",new String[]{"none","lantern","parcel","staff","rope"});
        ground=new CheckBox(a);ground.setText("Follow scene ground (preset actions)");ground.setChecked(true);form.addView(ground);
        custom=new CheckBox(a);custom.setText("Edit custom poses");form.addView(custom);poseForm=new LinearLayout(a);poseForm.setOrientation(1);form.addView(poseForm);
        selection=spinner(poseForm,"Selected pose",new String[]{"1"});poseFrame=input(poseForm,"Pose frame (1 based)","1");JSONObject poseDefaults=SketchHumanFigure.poseDefaults();for(String key:SketchHumanFigure.POSE_CHANNELS)channels.put(key,input(poseForm,key,String.valueOf(poseDefaults.get(key))));
        easing=spinner(poseForm,"Pose timing",new String[]{"smooth","linear","hold","ease_in","ease_out","ease_in_out","bezier"});curves=input(poseForm,"Bezier controls (JSON array)","[0.25,0.1,0.25,1]");
        button(poseForm,"Apply pose",()->{savePose(false);refresh();});button(poseForm,"Add pose",()->{savePose(true);refresh();});button(poseForm,"Delete pose",()->{if(selected==0)throw SketchDocument.bad("Keep the first pose at frame zero");poses.remove(selected);selected=Math.min(selected,poses.length()-1);refresh();});button(form,"Reset poses from action",this::reset);
        timed=new CheckBox(a);timed.setText("Timed speech");form.addView(timed);shotStart=input(form,"Shot start in master (ms)","0");speech=input(form,"Speech timing (editable JSON)","{\"transitionMs\":60,\"cues\":[{\"startMs\":0,\"endMs\":1,\"shape\":\"rest\"}]}");speech.setSingleLine(false);speech.setMinLines(3);button(form,"Load generated dialogue",this::loadSpeech);
        previewFrame=input(form,"Preview frame (1 based)",String.valueOf(count/2+1));button(form,"Use selected pose frame",this::selectFrame);button(form,"Preview human",this::preview);
        preview=new ImageView(a);preview.setContentDescription("Human animation preview");preview.setScaleType(ImageView.ScaleType.FIT_CENTER);form.addView(preview,new LinearLayout.LayoutParams(-1,260));status=new TextView(a);status.setContentDescription("Human animation status");form.addView(status);
        poses=SketchHumanPresets.create("listen",count,doc.getInt("fps"));refresh();poseForm.setVisibility(View.GONE);
        custom.setOnCheckedChangeListener((v,on)->{poseForm.setVisibility(on?View.VISIBLE:View.GONE);clear();});
        selection.setOnItemSelectedListener(changed(()->{if(selected==selection.getSelectedItemPosition())return;int next=selection.getSelectedItemPosition();try{int desiredFrame=poses.getJSONObject(next).getInt("frame");if(custom.isChecked())savePose(false);for(int i=0;i<poses.length();i++)if(poses.getJSONObject(i).getInt("frame")==desiredFrame){selected=i;break;}refresh();}catch(Exception e){binding=true;selection.setSelection(selected);binding=false;error(e);}}));preset.setOnItemSelectedListener(changed(()->{if(!custom.isChecked()){clear();try{reset();}catch(Exception e){error(e);}}else clear();}));
        for(Spinner s:new Spinner[]{view,build,hair,faceStyle,shading,clothing,easing,stageLocation,stageTime,stageWeather,propKind})s.setOnItemSelectedListener(changed(this::clear));TextWatcher watcher=new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){if(!binding)clear();}public void afterTextChanged(Editable e){}};
        for(EditText field:settings.values())field.addTextChangedListener(watcher);for(EditText field:channels.values())field.addTextChangedListener(watcher);speech.addTextChangedListener(watcher);previewFrame.addTextChangedListener(watcher);poseFrame.addTextChangedListener(watcher);curves.addTextChangedListener(watcher);motion.addTextChangedListener(watcher);overrides.addTextChangedListener(watcher);blinkTiming.addTextChangedListener(watcher);ground.setOnCheckedChangeListener((v,on)->clear());naturalBlink.setOnCheckedChangeListener((v,on)->clear());shotStart.addTextChangedListener(watcher);timed.setOnCheckedChangeListener((v,on)->clear());fit.setOnCheckedChangeListener((v,on)->clear());stageLocation.setOnItemSelectedListener(changed(()->{fit.setEnabled(stageLocation.getSelectedItem().equals("none"));clear();}));view.setOnItemSelectedListener(changed(()->{if(!custom.isChecked()){clear();try{reset();}catch(Exception e){error(e);}}else clear();}));
        constructionGuides.setOnCheckedChangeListener((v,on)->{if(!binding&&!closed&&!saving)clear();});
        figureStyle.setOnItemSelectedListener(changed(()->{syncFigureControls();clear();if(!custom.isChecked())try{reset();}catch(Exception e){error(e);}}));syncFigureControls();
    }
    private void show(){ScrollView scroll=new ScrollView(activity);scroll.addView(form);dialog=new AlertDialog.Builder(activity).setTitle("Human acting").setView(scroll).setPositiveButton("Create human",null).setNegativeButton("Cancel",null).create();dialog.setOnDismissListener(d->{closed=true;clear();worker.shutdownNow();});dialog.setOnShowListener(d->dialog.getButton(-1).setOnClickListener(v->{if(saving)return;try{JSONObject request=request();clear();final int attempt=++saveGeneration;saving=true;enable(form,false);dialog.setCancelable(false);dialog.getButton(-1).setEnabled(false);dialog.getButton(-2).setEnabled(false);status.setText("Creating native editable acting…");submit.submit(request,error->activity.runOnUiThread(()->{if(closed||attempt!=saveGeneration)return;saveGeneration++;if(error==null){dialog.dismiss();return;}saving=false;enable(form,true);syncFigureControls();dialog.setCancelable(true);dialog.getButton(-1).setEnabled(true);dialog.getButton(-2).setEnabled(true);status.setText("Human not created; controls retained: "+error.getMessage());}));}catch(Exception e){restoreSave(e);}}));dialog.show();}
    private void restoreSave(Exception failure){if(closed)return;saveGeneration++;saving=false;enable(form,true);syncFigureControls();if(dialog!=null){dialog.setCancelable(true);dialog.getButton(-1).setEnabled(true);dialog.getButton(-2).setEnabled(true);}error(failure);}
    private boolean anatomy(){return "anatomy_sketch".equals(figureStyle.getSelectedItem());}
    private void neutralAnatomyStance()throws Exception {
        JSONObject stance=new JSONObject().put("nearElbowSwivel",90).put("farElbowSwivel",-90).put("nearWrist",-6).put("farWrist",6);
        if(custom.isChecked()){
            for(String key:new String[]{"nearElbowSwivel","farElbowSwivel","nearWrist","farWrist"})channels.get(key).setText(String.valueOf(stance.get(key)));
            savePose(false);refresh();
        }else{
            JSONObject hold=new JSONObject(overrides.getText().toString());for(String key:new String[]{"nearElbowSwivel","farElbowSwivel","nearWrist","farWrist"})hold.put(key,stance.get(key));
            SketchHumanFigure.validatePose(hold);overrides.setText(hold.toString());reset();
        }
        clear();status.setText("Neutral anatomy stance: nearElbowSwivel 90, farElbowSwivel -90, nearWrist -6, farWrist 6. Applied to "+(custom.isChecked()?"the selected custom pose.":"preset pose overrides; other overrides retained."));
    }
    private void syncFigureControls(){
        boolean anatomy=anatomy();clothing.setEnabled(!saving&&!anatomy);constructionGuides.setEnabled(!saving&&anatomy);
        faceStyle.setEnabled(!saving&&!anatomy);shading.setEnabled(!saving&&!anatomy);settings.get("lightAngle").setEnabled(!saving&&!anatomy);
        String[] views=anatomy?ANATOMY_VIEWS:LEGACY_VIEWS;if(view.getCount()==views.length)return;
        String previous=view.getSelectedItem().toString();boolean wasBinding=binding;binding=true;
        try{view.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,views));int next=0;for(int i=0;i<views.length;i++)if(views[i].equals(previous))next=i;view.setSelection(next);}finally{binding=wasBinding;}
    }
    private JSONObject readSettings()throws Exception {JSONObject s=new JSONObject().put("view",view.getSelectedItem().toString()).put("build",build.getSelectedItem().toString()).put("hairStyle",hair.getSelectedItem().toString()).put("faceStyle",faceStyle.getSelectedItem().toString()).put("shading",shading.getSelectedItem().toString());if(anatomy())s.put("figureStyle","anatomy_sketch").put("constructionGuides",constructionGuides.isChecked());else if("tailored".equals(clothing.getSelectedItem().toString()))s.put("clothingStyle","tailored");for(Map.Entry<String,EditText> e:settings.entrySet())s.put(e.getKey(),e.getKey().endsWith("Color")?e.getValue().getText().toString().trim():Double.parseDouble(e.getValue().getText().toString().trim()));return SketchHumanFigure.settings(s);}
    private JSONObject operation(String id)throws Exception {JSONObject op=new JSONObject().put("type","add_human_animation").put("layerId",id).put("actorId",id).put("settings",readSettings()).put("preset",preset.getSelectedItem().toString());op.put("blinkTrack",naturalBlink.isChecked()?SketchHumanBlink.settings(new JSONObject(blinkTiming.getText().toString())):false);if(fit.isChecked()&&stageLocation.getSelectedItem().equals("none"))op.put("fit",true);if(!custom.isChecked()){JSONObject m=SketchHumanPresets.motion(new JSONObject(motion.getText().toString()));if(ground.isChecked()&&!stageLocation.getSelectedItem().equals("none")){m.remove("groundSlope");m.remove("groundSlopeX");op.put("ground",stageLocation.getSelectedItem().toString());}op.put("motion",m);JSONObject hold=new JSONObject(overrides.getText().toString());SketchHumanFigure.validatePose(hold);op.put("poseOverrides",hold);}if(custom.isChecked()){savePose(false);SketchHumanAnimation.validatePoses(poses,document.getInt("frameCount"));op.put("poses",new JSONArray(poses.toString()));}if(timed.isChecked()){JSONObject s=new JSONObject(speech.getText().toString());SketchSpeechTiming.validate(s,duration());op.put("speech",s);}return op;}
    private JSONObject request()throws Exception {
        String id="human_"+UUID.randomUUID().toString().replace("-","").substring(0,14);JSONArray ops=new JSONArray();boolean stage=!stageLocation.getSelectedItem().equals("none");String back="back_"+id,front="front_"+id;
        if(stage){ops.put(new JSONObject().put("type","add_layer").put("layer",new JSONObject().put("id",back).put("name","Scene background")));ops.put(new JSONObject().put("type","reorder_layer").put("layerId",back).put("index",0));}
        if(propKind.getSelectedItem().equals("rope"))ops.put(new JSONObject().put("type","add_layer").put("layer",new JSONObject().put("id","link_"+id).put("name","Hand link")));
        ops.put(new JSONObject().put("type","add_layer").put("layer",new JSONObject().put("id",id).put("name","Human acting"))).put(operation(id));
        if(stage){ops.put(new JSONObject().put("type","add_layer").put("layer",new JSONObject().put("id",front).put("name","Scene foreground")));ops.put(new JSONObject().put("type","add_story_stage").put("layerId",back).put("foregroundLayerId",front).put("sceneId","s_"+id.substring(2)).put("settings",new JSONObject().put("location",stageLocation.getSelectedItem().toString()).put("time",stageTime.getSelectedItem().toString()).put("weather",stageWeather.getSelectedItem().toString()).put("intensity",.6)));}
        if(propKind.getSelectedItem().equals("rope"))ops.put(new JSONObject().put("type","add_grip_link").put("layerId","link_"+id).put("linkId","l_"+id.substring(2)).put("from",new JSONObject().put("actorId",id).put("hand","near")).put("to",new JSONObject().put("actorId",id).put("hand","far")).put("settings",new JSONObject()));
        else if(!propKind.getSelectedItem().equals("none"))ops.put(new JSONObject().put("type","add_actor_prop").put("layerId",id).put("actorId",id).put("propId","p_"+id.substring(2)).put("settings",new JSONObject().put("kind",propKind.getSelectedItem().toString()).put("attachment","near").put("scale",1)));
        return new JSONObject().put("operations",ops);
    }
    private void reset()throws Exception {poses=SketchHumanAnimation.presetPoses(preset.getSelectedItem().toString(),document.getInt("frameCount"),document.getInt("fps"),new JSONObject(motion.getText().toString()),view.getSelectedItem().toString(),new JSONObject(overrides.getText().toString()));selected=0;refresh();status.setText("Editable action poses reset.");}
    private void savePose(boolean add)throws Exception {JSONObject p=new JSONObject().put("frame",Integer.parseInt(poseFrame.getText().toString().trim())-1).put("interpolation",easing.getSelectedItem().toString());for(Map.Entry<String,EditText> e:channels.entrySet())p.put(e.getKey(),Double.parseDouble(e.getValue().getText().toString().trim()));if(p.getString("interpolation").equals("bezier"))p.put("curve",new JSONArray(curves.getText().toString()));List<JSONObject> list=new ArrayList<>();for(int i=0;i<poses.length();i++)if(add||i!=selected)list.add(poses.getJSONObject(i));list.add(p);list.sort(Comparator.comparingInt(x->x.optInt("frame")));JSONArray next=new JSONArray(list);SketchHumanAnimation.validatePoses(next,document.getInt("frameCount"));poses=next;selected=list.indexOf(p);clear();}
    private void refresh()throws Exception {binding=true;try{String[] labels=new String[poses.length()];for(int i=0;i<labels.length;i++)labels[i]="Frame "+(poses.getJSONObject(i).getInt("frame")+1);selection.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,labels));selection.setSelection(selected);JSONObject p=poses.getJSONObject(selected),defaults=SketchHumanFigure.poseDefaults();poseFrame.setText(String.valueOf(p.getInt("frame")+1));for(Map.Entry<String,EditText> e:channels.entrySet())e.getValue().setText(String.valueOf(p.opt(e.getKey())==null?defaults.get(e.getKey()):p.get(e.getKey())));String mode=p.optString("interpolation","smooth");for(int i=0;i<easing.getCount();i++)if(mode.equals(easing.getItemAtPosition(i)))easing.setSelection(i);if(p.has("curve"))curves.setText(p.getJSONArray("curve").toString());}finally{binding=false;}clear();}
    private void selectFrame()throws Exception {previewFrame.setText(String.valueOf(poses.getJSONObject(selected).getInt("frame")+1));}
    private void preview()throws Exception {JSONObject req=request();int frame=Integer.parseInt(previewFrame.getText().toString().trim())-1;if(frame<0||frame>=document.getInt("frameCount"))throw SketchDocument.bad("Choose a preview frame inside this timeline");clear();int current=++generation;status.setText("Rendering native human preview…");task=worker.submit(()->{Bitmap image=null;try{JSONObject d=SketchDocument.copy(document);JSONArray ops=req.getJSONArray("operations");for(int i=0;i<ops.length();i++)SketchEditOps.apply(d,ops.getJSONObject(i));try(SketchFrameRenderer renderer=new SketchFrameRenderer(activity,d)){image=renderer.render(frame);}final Bitmap result=image;activity.runOnUiThread(()->{if(unavailable()||current!=generation){result.recycle();return;}bitmap=result;preview.setImageBitmap(result);status.setText("Native human preview · frame "+(frame+1)+". No audio playback.");});}catch(Exception e){if(image!=null)image.recycle();activity.runOnUiThread(()->{if(!unavailable()&&current==generation)error(e);});}});}
    private void loadSpeech()throws Exception {
        long offset=Long.parseLong(shotStart.getText().toString().trim());if(offset<0||offset>600000)throw SketchDocument.bad("Shot start must be0..600000ms");clear();final int request=generation;status.setText("Checking imported dialogue…");
        speechTask=worker.submit(()->{try{JSONArray choices=SketchSpeechAssets.choices(activity);String[] labels=new String[choices.length()];for(int i=0;i<labels.length;i++)labels[i]=choices.getJSONObject(i).getString("label");activity.runOnUiThread(()->{
            if(unavailable()||generation!=request)return;new AlertDialog.Builder(activity).setTitle("Imported generated lines").setItems(labels,(d,which)->{
                if(unavailable()||generation!=request)return;speechTask=worker.submit(()->{try{JSONObject ref=choices.getJSONObject(which),loaded=SketchSpeechAssets.load(activity,ref.getString("requestId"),ref.getInt("lineIndex"),duration(),offset);activity.runOnUiThread(()->{
                    if(unavailable()||generation!=request)return;try{speech.setText(loaded.getJSONObject("speech").toString(2));timed.setChecked(true);status.setText(loaded.getString("text")+"\nUse unchanged master audio at the film origin; this shot starts at "+offset+"ms. Model timing needs review.");}catch(Exception e){error(e);}
                });}catch(Exception e){activity.runOnUiThread(()->{if(!unavailable()&&generation==request)error(e);});}});
            }).setNegativeButton("Cancel",null).show();
        });}catch(Exception e){activity.runOnUiThread(()->{if(!unavailable()&&generation==request)error(e);});}});
    }
    private double duration(){return document.optInt("frameCount")*1000d/document.optInt("fps");}
    private boolean unavailable(){return closed||activity.isFinishing()||activity.isDestroyed();}
    private void clear(){generation++;if(speechTask!=null){speechTask.cancel(true);speechTask=null;}if(task!=null){task.cancel(true);task=null;}preview.setImageDrawable(null);if(bitmap!=null){bitmap.recycle();bitmap=null;}}
    private void error(Exception e){status.setText("Controls retained: "+e.getMessage());}
    private void button(LinearLayout parent,String label,Action action){Button b=new Button(activity);b.setText(label);parent.addView(b);b.setOnClickListener(v->{if(unavailable()||saving)return;try{action.run();}catch(Exception e){error(e);}});}
    private interface Action{void run()throws Exception;}
    private EditText input(LinearLayout parent,String name,String value){TextView label=new TextView(activity);label.setText(name);parent.addView(label);EditText field=new EditText(activity);field.setContentDescription(name);field.setSingleLine(true);field.setText(value);parent.addView(field);return field;}
    private Spinner spinner(LinearLayout parent,String name,String[] values){TextView label=new TextView(activity);label.setText(name);parent.addView(label);Spinner s=new Spinner(activity);s.setContentDescription(name);s.setAdapter(new ArrayAdapter<>(activity,android.R.layout.simple_spinner_dropdown_item,values));parent.addView(s);return s;}
    private AdapterView.OnItemSelectedListener changed(Runnable action){return new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?> p){}public void onItemSelected(AdapterView<?> p,View v,int n,long id){if(!binding&&!closed&&!saving)action.run();}};}
    private static void enable(View v,boolean on){v.setEnabled(on);if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)enable(((ViewGroup)v).getChildAt(i),on);}
}
